// Integral degree-6 reference resolution: t**6 + 2*t**4 - 3*t**2 + t + 1.
function MonogenicResolution6_mixed(R)
    P<[x]> := PolynomialRing(R,5);
    F := [* *];
    Append(~F,Matrix(P,1,9,[
        (1*x[2]^2 + -1*x[1]*x[3]),(1*x[2]*x[3] + -1*x[1]*x[4]),(1*x[2]*x[4] + -1*x[1]*x[5]),(1*x[3]^2 + -1*x[1]*x[5]),(1*x[3]*x[4] + -1*x[2]*x[5]),(1*x[4]^2 + -1*x[3]*x[5]),(1*x[3]*x[5] + 2*x[1]*x[5] + -3*x[1]*x[3] + 1*x[1]*x[2] + 1*x[1]^2),(1*x[4]*x[5] + 2*x[2]*x[5] + -3*x[1]*x[4] + 1*x[1]*x[3] + 1*x[1]*x[2]),
        (1*x[5]^2 + 2*x[3]*x[5] + -3*x[1]*x[5] + 1*x[1]*x[4] + 1*x[1]*x[3])
    ]));
    Append(~F,Matrix(P,9,16,[
        (1*x[3]),(1*x[4]),(1*x[4]),(1*x[5]),P!0,P!0,P!0,P!0,
        (1*x[1]),(-2*x[5] + 3*x[3] + -1*x[1]),(1*x[3]),(1*x[4]),(3*x[3]),(3*x[4]),(1*x[4] + 1*x[3]),(1*x[4]),
        (-1*x[2]),(-1*x[3]),P!0,P!0,(1*x[5]),(1*x[4]),(1*x[5]),P!0,
        (1*x[5] + -3*x[1]),(-3*x[2]),(-2*x[5] + -1*x[2] + -1*x[1]),(-3*x[4]),(-3*x[2] + 1*x[1]),(-2*x[5] + -1*x[1]),(-1*x[2]),(1*x[4]),
        (-1*x[1]),(-1*x[2]),(-1*x[2]),(-1*x[3]),P!0,(-1*x[3]),(-1*x[4]),(-1*x[5]),
        P!0,(-1*x[5]),P!0,(-2*x[5] + 3*x[3] + -1*x[2] + -1*x[1]),(-3*x[1]),(-3*x[2]),(-1*x[2] + -1*x[1]),(-1*x[3] + -1*x[2]),
        (1*x[1]),(1*x[2]),P!0,P!0,(-1*x[4]),P!0,P!0,(1*x[5]),
        P!0,(1*x[5]),P!0,P!0,(1*x[5]),P!0,(-2*x[5]),P!0,
        P!0,P!0,(1*x[1]),(1*x[2]),(1*x[3]),P!0,P!0,(-1*x[4]),
        P!0,P!0,P!0,P!0,P!0,(1*x[5]),P!0,(-2*x[5]),
        P!0,P!0,P!0,P!0,P!0,(1*x[1]),(1*x[2]),(1*x[3]),
        P!0,P!0,P!0,(-1*x[5]),P!0,P!0,P!0,P!0,
        P!0,P!0,P!0,P!0,P!0,P!0,P!0,P!0,
        (-1*x[2]),(-1*x[3]),(-1*x[4]),(-1*x[5]),(-1*x[3]),(-1*x[4]),(-1*x[5]),P!0,
        P!0,P!0,P!0,P!0,P!0,P!0,P!0,P!0,
        (1*x[1]),(1*x[2]),(1*x[3]),(1*x[4]),P!0,P!0,P!0,(-1*x[5]),
        P!0,P!0,P!0,P!0,P!0,P!0,P!0,P!0,
        P!0,P!0,P!0,P!0,(1*x[1]),(1*x[2]),(1*x[3]),(1*x[4])
    ]));
    Append(~F,Matrix(P,16,9,[
        (-1*x[4]),(-1*x[5]),P!0,(3*x[2]),(2*x[5] + 1*x[2]),(-1*x[2]),(3*x[4]),P!0,
        (1*x[4]),P!0,(-1*x[4]),(-1*x[5]),(1*x[5] + -3*x[1]),(-1*x[1]),(2*x[5] + 1*x[1]),P!0,
        (3*x[4]),(1*x[4]),(1*x[3]),(1*x[4]),P!0,(-1*x[5]),P!0,P!0,
        (2*x[5] + -3*x[3] + 1*x[2]),(-1*x[2]),(-1*x[3]),P!0,(1*x[3]),(1*x[4]),P!0,P!0,
        P!0,(-1*x[1]),(2*x[5] + -3*x[3] + 1*x[1]),(-1*x[3]),(-1*x[1]),(-1*x[2]),P!0,P!0,
        P!0,(1*x[5]),(3*x[1]),(3*x[2]),(2*x[5] + 1*x[2] + 1*x[1]),(-1*x[2]),(-1*x[3]),P!0,
        P!0,(-1*x[5]),P!0,P!0,P!0,P!0,(1*x[1]),P!0,
        (-1*x[3]),P!0,P!0,(-1*x[5]),(-1*x[5]),P!0,P!0,P!0,
        (1*x[1]),(1*x[2]),P!0,P!0,P!0,P!0,(-1*x[5]),P!0,
        P!0,P!0,P!0,(1*x[3]),(1*x[4]),P!0,(1*x[5]),P!0,
        P!0,P!0,P!0,P!0,P!0,(1*x[3]),(1*x[4]),(1*x[4]),
        (1*x[5]),P!0,P!0,P!0,P!0,(-1*x[1]),(-1*x[2]),P!0,
        P!0,(1*x[4]),(1*x[5]),P!0,P!0,P!0,P!0,(-1*x[1]),
        (-1*x[2]),(-1*x[2]),(-1*x[3]),P!0,P!0,P!0,P!0,(-1*x[2]),
        (-1*x[3]),P!0,(-1*x[4]),P!0,P!0,P!0,P!0,P!0,
        (1*x[1]),P!0,(-1*x[3]),P!0,(-1*x[4]),P!0,P!0,P!0,
        P!0,P!0,(1*x[1]),(1*x[2]),P!0,P!0,(-1*x[4]),P!0,
        P!0,P!0,P!0,P!0,P!0,(1*x[1]),(1*x[2]),(1*x[3])
    ]));
    Append(~F,Matrix(P,9,1,[
        (-1*x[5]^2 + -2*x[3]*x[5] + 3*x[3]^2 + -1*x[2]*x[3] + -1*x[1]*x[3]),(1*x[4]*x[5] + 2*x[2]*x[5] + -3*x[2]*x[3] + 1*x[2]^2 + 1*x[1]*x[2]),(-1*x[3]*x[5] + -2*x[1]*x[5] + 3*x[1]*x[3] + -1*x[1]*x[2] + -1*x[1]^2),(1*x[4]^2 + -1*x[3]*x[5]),(-1*x[3]*x[4] + 1*x[2]*x[5]),(1*x[2]*x[4] + -1*x[1]*x[5]),(1*x[3]^2 + -1*x[2]*x[4]),(-1*x[2]*x[3] + 1*x[1]*x[4]),
        (1*x[2]^2 + -1*x[1]*x[3])
    ]));
    return F;
end function;
